// Extract, sanitize, and generate deterministic dedupe key for lead
const crypto = require('crypto');
const body = $input.item.json.body || $input.item.json;

const email = (body.email || body.lead_email || '').trim().toLowerCase();
const firstName = (body.first_name || body.firstName || '').trim();
const lastName = (body.last_name || body.lastName || '').trim();
const fullName = (body.name || `${firstName} ${lastName}`).trim() || 'New Prospect';
const company = (body.company || body.organization || 'Independent').trim();
const phone = (body.phone || body.telephone || '').trim();
const stage = (body.stage || body.status || 'New Lead').trim();
const dealValue = parseFloat(body.deal_value || body.value || 0);
const source = (body.source || 'Website Inbound').trim();

if (!email) {
  throw new Error('Missing required unique field: email is required for deduplication.');
}

// Generate deterministic deduplication hash from canonical email
const dedupeHash = crypto.createHash('sha256').update(email).digest('hex').slice(0, 16);
const nowIso = new Date().toISOString();

return {
  json: {
    lead_id: body.id || `lead_${dedupeHash}`,
    dedupe_hash: dedupeHash,
    email,
    full_name: fullName,
    first_name: firstName,
    last_name: lastName,
    company,
    phone,
    stage,
    deal_value: dealValue,
    source,
    timestamp: nowIso
  }
};

