// Inspect Turso LibSQL response to evaluate if lead exists
const tursoRes = $input.item.json;
const leadMeta = $('Normalize & Hash Lead').first().json;

const queryResult = tursoRes.results?.[0]?.response?.result;
const rows = queryResult?.rows || [];
const leadExists = rows.length > 0;

return {
  json: {
    ...leadMeta,
    lead_exists: leadExists,
    existing_record: leadExists ? rows[0] : null
  }
};

